-- ============================================================
-- 商城秒杀系统 —— PostgreSQL Schema
--
-- 环境一致性：本地 Docker Postgres 与线上 Supabase Postgres 方言完全相同
-- 执行时机：docker compose 首次启动时自动执行；也可手动 psql -f schema.sql
-- 幂等性：全部使用 IF NOT EXISTS，可重复执行
--
-- 与 MySQL 版本的差异（迁移要点）：
--   BIGINT AUTO_INCREMENT  -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DATETIME               -> TIMESTAMP
--   TINYINT                -> SMALLINT
--   ON UPDATE CURRENT_TIMESTAMP -> 应用层维护（MyBatis-Plus 自动填充）
--   ENGINE=InnoDB / CHARSET    -> 不需要
--   CREATE TABLE 内联 INDEX    -> 必须拆成独立 CREATE INDEX
-- ============================================================


-- ------------------------------------------------------------
-- 1. 用户表
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS t_user (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(64)  NOT NULL,
    password      VARCHAR(128) NOT NULL,                    -- BCrypt 哈希（盐已内嵌）
    created_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_username UNIQUE (username)
);


-- ------------------------------------------------------------
-- 2. 商品表（常规售卖）
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS goods (
    id           BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(128)  NOT NULL,
    price        NUMERIC(10,2) NOT NULL,                    -- 常规售卖价
    stock        INT           NOT NULL DEFAULT 0,          -- 商品总库存
    detail       TEXT,
    create_time  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);


-- ------------------------------------------------------------
-- 3. 秒杀活动商品表
--    与 goods 解耦：同一商品可开多次秒杀，活动库存独立
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS seckill_goods (
    id             BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    goods_id       BIGINT        NOT NULL,
    seckill_price  NUMERIC(10,2) NOT NULL,
    stock_count    INT           NOT NULL DEFAULT 0,        -- 秒杀库存（Redis 未命中时的兜底真值）
    start_time     TIMESTAMP     NOT NULL,
    end_time       TIMESTAMP     NOT NULL,
    CONSTRAINT fk_seckill_goods_goods FOREIGN KEY (goods_id) REFERENCES goods (id)
);

CREATE INDEX IF NOT EXISTS idx_seckill_goods_goods_id ON seckill_goods (goods_id);
CREATE INDEX IF NOT EXISTS idx_seckill_goods_time     ON seckill_goods (start_time, end_time);


-- ------------------------------------------------------------
-- 4. 订单主表
--    id 由雪花算法生成，不做自增：批量插入后无需回查即可拿到订单号
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS order_info (
    id           BIGINT        PRIMARY KEY,                 -- 雪花 ID
    user_id      BIGINT        NOT NULL,
    goods_id     BIGINT        NOT NULL,
    goods_name   VARCHAR(128)  NOT NULL,                    -- 商品名快照
    order_price  NUMERIC(10,2) NOT NULL,                    -- 成交价快照
    status       SMALLINT      NOT NULL DEFAULT 0,          -- 0待支付 1已支付 2已发货 3已完成 4已取消 5已退款
    version      INT           NOT NULL DEFAULT 1,          -- 乐观锁版本号（防状态机乱序）
    create_time  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time  TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pay_time     TIMESTAMP     NULL
);

CREATE INDEX IF NOT EXISTS idx_order_user_time ON order_info (user_id, create_time DESC);
CREATE INDEX IF NOT EXISTS idx_order_status    ON order_info (status, create_time);


-- ------------------------------------------------------------
-- 5. 秒杀幂等表（防重复下单）
--
--    ★ 这是"不重复下单"这条不变量的最后防线：
--      代码判断在并发下不可靠，唯一索引才是真的可靠。
--      即使 Redis 判重被绕过，这里也会拒绝第二条插入。
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS seckill_order (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id   BIGINT NOT NULL,
    order_id  BIGINT NOT NULL,                              -- 关联 order_info.id
    goods_id  BIGINT NOT NULL,
    CONSTRAINT uk_seckill_order_user_goods UNIQUE (user_id, goods_id)
);

CREATE INDEX IF NOT EXISTS idx_seckill_order_order_id ON seckill_order (order_id);


-- ------------------------------------------------------------
-- 6. 事务性发件箱表 (Transactional Outbox Pattern)
--
--    ★ 解决分布式事务假一致性：
--      将“业务数据写库”与“事件消息投递”绑定在同一个本地事务中。
--      由可靠投递引擎以 FOR UPDATE SKIP LOCKED 异步推向 Kafka。
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS t_outbox (
    id              BIGINT        PRIMARY KEY,                 -- 雪花 ID
    aggregate_type  VARCHAR(64)   NOT NULL,                    -- 聚合根类型: "ORDER"
    aggregate_id    BIGINT        NOT NULL,                    -- 聚合根 ID: order_id
    event_type      VARCHAR(64)   NOT NULL,                    -- 事件类型: "ORDER_CREATED"
    topic           VARCHAR(128)  NOT NULL,                    -- 目标 Kafka Topic
    payload         TEXT          NOT NULL,                    -- JSON 载荷
    status          SMALLINT      NOT NULL DEFAULT 0,          -- 0待投递 1投递成功 2投递失败
    retry_count     INT           NOT NULL DEFAULT 0,          -- 失败重试次数
    error_msg       TEXT,                                      -- 异常信息
    create_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_outbox_status_create ON t_outbox (status, create_time);

-- ------------------------------------------------------------
-- 7. 场馆物理选座表 (Physical Seat Selection & Reservation)
--
--    ★ 商业级全真选座与 Bitmap 位图映射：
--      seat_index 对应场馆连续 bit 偏移量 (0-based)
--      status: 0-空闲可选, 1-临时锁定待付款, 2-已售出
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS d_seat (
    id              BIGINT        PRIMARY KEY,                 -- 雪花 ID
    program_id      BIGINT        NOT NULL,                    -- 演出 ID
    category_id     BIGINT        NOT NULL,                    -- 票档 ID
    area            VARCHAR(64)   NOT NULL,                    -- 区域名称: 南看台A区
    row_num         INT           NOT NULL,                    -- 排号
    col_num         INT           NOT NULL,                    -- 座号
    seat_index      INT           NOT NULL,                    -- 物理位图偏移下标
    status          SMALLINT      NOT NULL DEFAULT 0,          -- 0可选 1锁定中 2已售出
    lock_user_id    BIGINT,                                    -- 临时锁定的用户ID
    lock_time       TIMESTAMP,                                 -- 临时锁定时间
    version         INT           NOT NULL DEFAULT 0,          -- 乐观锁版本号
    create_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_program_seat_index ON d_seat(program_id, seat_index);
CREATE INDEX IF NOT EXISTS idx_program_category ON d_seat(program_id, category_id);

-- ------------------------------------------------------------
-- 8. 营销优惠券中心 (Marketing Coupon Engine)
--
--    ★ 防超发、多态资产生命周期与最优抵扣：
--      d_coupon_template: 优惠券模板（满减、折扣、立减）
--      d_coupon_user: 用户持有的优惠券资产 (0未使用 1冻结 2已核销 3已失效)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS d_coupon_template (
    id                  BIGINT          PRIMARY KEY,                  -- 模板ID
    name                VARCHAR(128)    NOT NULL,                     -- 优惠券名称
    type                SMALLINT        NOT NULL,                     -- 1:满减券, 2:折扣券, 3:无门槛立减
    threshold_amount    NUMERIC(10, 2)  NOT NULL DEFAULT 0.00,        -- 使用门槛金额 (0表示无门槛)
    discount_amount     NUMERIC(10, 2)  NOT NULL DEFAULT 0.00,        -- 满减/立减减免金额
    discount_rate       NUMERIC(5, 2),                                -- 折扣率 (如 0.85 表示 85折)
    max_discount_amount NUMERIC(10, 2),                               -- 折扣券最高减免封顶金额
    total_quota         INT             NOT NULL,                     -- 总发放配额
    remain_quota        INT             NOT NULL,                     -- 剩余未领取配额
    valid_start_time    TIMESTAMP       NOT NULL,                     -- 有效期起始时间
    valid_end_time      TIMESTAMP       NOT NULL,                     -- 有效期截止时间
    status              SMALLINT        NOT NULL DEFAULT 1,           -- 1:启用, 0:停用
    create_time         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS d_coupon_user (
    id                  BIGINT          PRIMARY KEY,                  -- 用户券ID
    coupon_code         VARCHAR(64)     UNIQUE NOT NULL,              -- 唯一防伪券码
    user_id             BIGINT          NOT NULL,                     -- 持有用户ID
    template_id         BIGINT          NOT NULL,                     -- 归属模板ID
    status              SMALLINT        NOT NULL DEFAULT 0,           -- 0:未使用, 1:冻结锁定中, 2:已核销使用, 3:已失效
    order_id            BIGINT,                                       -- 关联消费的订单ID
    used_time           TIMESTAMP,                                    -- 核销时间
    create_time         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time         TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_user_template ON d_coupon_user(user_id, template_id);
CREATE INDEX IF NOT EXISTS idx_coupon_user_status ON d_coupon_user(user_id, status);

